//! The per-version schema: declarative field tables (data only) plus the record
//! layouts they describe. A bit offset appears in `schema/pesNN.rs` or nowhere;
//! `codec/` interprets these tables and never carries one itself. The table
//! modules are generated by `scripts/derive_savefile_schema.py` (method:
//! `docs/spec/pes_savefile/codec.md`, "Schema-driven save codec").

/// The version-neutral field vocabularies the tables name.
pub mod fields;
/// The ingame-face run's field table, hand-written (the run is opaque bytes
/// the table names known bits of).
pub mod ingame_face;
/// The per-version advanced-instruction mappings (`decode`/`encode` between a
/// stored value and `model::instruction::Instruction`).
pub mod instruction;
#[cfg(test)]
mod instruction_golden;
/// The per-version caps on the ingame-face type fields.
pub mod limits;
mod pes15;
mod pes16;
mod pes17;
mod pes18;
mod pes19;
mod pes20;
/// The per-version playing-style lists (`decode`/`encode` between a stored
/// index and `model::playstyle::PlayStyle`).
pub mod playstyle;
#[cfg(test)]
mod playstyle_golden;
/// The per-version Texport file layouts (18-21) and payload offsets (15-17).
pub mod texport;

use pes_version::PesVersion;

use fields::{
    PlayerField, PlayerText, PresetField, RosterField, TacticsField, TeamField, TeamText,
};

/// One bit run of a record.
pub struct FieldSpec<F> {
    /// The model field the run decodes to.
    pub field: F,
    /// Bit position from the record's first byte.
    pub bit_offset: u32,
    /// Run length in bits.
    pub bit_width: u32,
}

/// A regular run of indexed fields (`play_skill[0..41]`, roster slots, formation players):
/// element `i` is `make(i)` at `base_bit + i * stride_bits`.
pub struct ArraySpec<F> {
    /// Builds the indexed field variant for element `i`.
    pub make: fn(u8) -> F,
    /// Element count.
    pub count: u8,
    /// Bit position of element 0.
    pub base_bit: u32,
    /// Bits between consecutive elements.
    pub stride_bits: u32,
    /// Bits per element.
    pub bit_width: u32,
}

/// A byte string field: NUL-terminated when the text is shorter than the field, unterminated
/// when it fills the field exactly.
pub struct TextSpec<T> {
    /// The model text the bytes decode to.
    pub text: T,
    /// Byte offset from the record's first byte.
    pub byte_offset: u32,
    /// Byte length of the whole field.
    pub len: u32,
}

/// A byte run carried verbatim.
pub struct ByteRun {
    /// Byte offset from the record's first byte.
    pub byte_offset: u32,
    /// Byte length.
    pub len: u32,
}

/// One record kind's layout for one version (player, appearance, team, roster).
pub struct RecordSchema<F: 'static, T: 'static> {
    /// Record size in bytes.
    pub size: usize,
    /// The scalar bit runs.
    pub fields: &'static [FieldSpec<F>],
    /// The indexed runs.
    pub arrays: &'static [ArraySpec<F>],
    /// The text fields.
    pub texts: &'static [TextSpec<T>],
    /// The opaque ingame-face run: `Some` on the record that carries the
    /// appearance block (the 15/16 appearance record, the 17+ player record).
    pub ingame_face: Option<ByteRun>,
}

impl<F: PartialEq + Copy, T> RecordSchema<F, T> {
    /// The bit width the record stores `field` at, from its `fields` row or
    /// the `arrays` run whose `make(i)` produces it; `None` for a field the
    /// record does not store.
    pub(crate) fn bit_width(&self, field: F) -> Option<u32> {
        if let Some(spec) = self.fields.iter().find(|spec| spec.field == field) {
            return Some(spec.bit_width);
        }
        self.arrays.iter().find_map(|array| {
            (0..array.count)
                .any(|i| (array.make)(i) == field)
                .then_some(array.bit_width)
        })
    }

    /// Whether the schema stores `field`.
    pub fn has(&self, field: F) -> bool {
        self.bit_width(field).is_some()
    }

    /// The biggest value the record stores in `field` (`2^width - 1`, the codec's
    /// `ValueTooWide` bound); `None` for a field the record does not store.
    pub fn max_value(&self, field: F) -> Option<u64> {
        self.bit_width(field).map(|width| (1u64 << width) - 1)
    }
}

/// A per-preset setting: one byte at `bit_offset + preset * preset_stride_bits`.
pub struct PresetSpec {
    /// The tactic setting the byte holds.
    pub field: PresetField,
    /// Bit position inside the preset's block.
    pub bit_offset: u32,
}

/// The 3 x 3 formation blocks: player `slot`'s position byte at
/// `base + preset * preset_stride + formation * formation_stride + slot * slot_stride`, its
/// y then x bytes at `.. + y_offset + slot * pair_stride` and `.. + x_offset + ..`.
pub struct FormationLayout {
    /// Bit position of formation 0's first slot within a preset block.
    pub base_bit: u32,
    /// Bits between consecutive formations.
    pub formation_stride_bits: u32,
    /// Bits between consecutive position bytes.
    pub slot_stride_bits: u32,
    /// Bits from the formation's first position byte to the y/x pair block.
    pub y_offset_bits: u32,
    /// Bits from the formation's first position byte to the x byte of each pair.
    pub x_offset_bits: u32,
    /// Bits between consecutive y/x pairs.
    pub pair_stride_bits: u32,
}

/// The advanced instructions (PES 17+): one part at
/// `base + preset * preset_stride + side * side_stride + index * index_stride + part * part_stride`.
pub struct InstructionLayout {
    /// Bit position of the first instruction's first part within a preset block.
    pub base_bit: u32,
    /// Bits between the attacking and defending instructions.
    pub side_stride_bits: u32,
    /// Bits between the two instructions of a side.
    pub index_stride_bits: u32,
    /// Bits between an instruction's id and its player id.
    pub part_stride_bits: u32,
}

/// The tactics record: the scalar and array fields plus the three regular nested blocks,
/// which the derivation checks are regular before emitting them this way.
pub struct TacticsSchema {
    /// Record size in bytes.
    pub size: usize,
    /// The scalar bit runs.
    pub fields: &'static [FieldSpec<TacticsField>],
    /// The indexed runs.
    pub arrays: &'static [ArraySpec<TacticsField>],
    /// Bits between consecutive preset blocks.
    pub preset_stride_bits: u32,
    /// Bit position of the preset's eleven man-marking bytes within a preset
    /// block (byte `i` is own formation slot `i`'s assignment).
    pub man_marking_bit: u32,
    /// The per-preset settings.
    pub presets: &'static [PresetSpec],
    /// The formation block layout.
    pub formations: FormationLayout,
    /// The advanced-instruction block layout; `None` on PES 15/16.
    pub instructions: Option<InstructionLayout>,
}

impl TacticsSchema {
    /// Whether the tactics record stores `field` (scalar fields and arrays, as
    /// `RecordSchema::has`; preset settings via [`Self::has_preset`],
    /// formations always, instructions when `instructions` is `Some`, man
    /// marking for a preset of 0 to 2 and a slot of 0 to 10).
    pub fn has(&self, field: TacticsField) -> bool {
        if let TacticsField::Preset { field, .. } = field {
            return self.has_preset(field);
        }
        if let TacticsField::Formation { .. } = field {
            return true;
        }
        if let TacticsField::Instruction { .. } = field {
            return self.instructions.is_some();
        }
        if let TacticsField::ManMarking { preset, slot } = field {
            return preset < 3 && slot < 11;
        }
        self.fields.iter().any(|spec| spec.field == field)
            || self
                .arrays
                .iter()
                .any(|array| (0..array.count).any(|i| (array.make)(i) == field))
    }

    /// Whether each preset block stores `field`.
    pub fn has_preset(&self, field: PresetField) -> bool {
        self.presets.iter().any(|spec| spec.field == field)
    }
}

/// Where a section of records sits in the payload.
pub struct SectionLayout {
    /// Byte offset of the first record.
    pub offset: usize,
    /// Byte offset of the little-endian u16 record count.
    pub count_offset: usize,
}

/// Every section's layout for one game version.
pub struct VersionSchema {
    /// The version these tables describe.
    pub version: PesVersion,
    /// The player record section.
    pub players: SectionLayout,
    /// The player record layout.
    pub player: &'static RecordSchema<PlayerField, PlayerText>,
    /// PES 15/16: the separate appearance array (keyed by player id at +0); `None` when the
    /// appearance fields are inside the player record.
    pub appearance: Option<(
        SectionLayout,
        &'static RecordSchema<PlayerField, PlayerText>,
    )>,
    /// The team record section.
    pub teams: SectionLayout,
    /// The team record layout.
    pub team: &'static RecordSchema<TeamField, TeamText>,
    /// The roster record section.
    pub rosters: SectionLayout,
    /// The roster record layout.
    pub roster: &'static RecordSchema<RosterField, TeamText>,
    /// The tactics record section.
    pub tactics: SectionLayout,
    /// The tactics record layout.
    pub tactic: &'static TacticsSchema,
}

impl VersionSchema {
    /// Whether `field` is stored for a player of this version: in the player
    /// record, or in the separate appearance record on PES 15/16.
    pub fn player_has(&self, field: PlayerField) -> bool {
        self.player.has(field)
            || self
                .appearance
                .as_ref()
                .is_some_and(|(_, appearance)| appearance.has(field))
    }

    /// Every `PlayerField` `player_has` answers `true` for, as a set: callers
    /// gating many keys against one version build it once instead of paying
    /// `player_has`'s field-table scan per key.
    pub fn player_field_set(&self) -> std::collections::HashSet<PlayerField> {
        fn collect(
            schema: &RecordSchema<PlayerField, PlayerText>,
            set: &mut std::collections::HashSet<PlayerField>,
        ) {
            set.extend(schema.fields.iter().map(|spec| spec.field));
            for array in schema.arrays {
                set.extend((0..array.count).map(|i| (array.make)(i)));
            }
        }
        let mut set = std::collections::HashSet::new();
        collect(self.player, &mut set);
        if let Some((_, appearance)) = self.appearance {
            collect(appearance, &mut set);
        }
        set
    }
}

/// The field tables of one game version. PES 20 and 21 share one player table;
/// PES 21's team record carries its own layout.
pub fn schema_for(version: PesVersion) -> &'static VersionSchema {
    match version {
        PesVersion::Pes15 => &pes15::PES15,
        PesVersion::Pes16 => &pes16::PES16,
        PesVersion::Pes17 => &pes17::PES17,
        PesVersion::Pes18 => &pes18::PES18,
        PesVersion::Pes19 => &pes19::PES19,
        PesVersion::Pes20 => &pes20::PES20,
        PesVersion::Pes21 => &pes20::PES21,
    }
}

/// The Fox `PlayerAppearance.bin` row's 56 appearance bytes' offset inside
/// the version's player record: right where the appearance block's
/// base-copy id ends: record bytes 128 to 184 on PES 18/19, 252 to 308 on
/// PES 20/21. The games' own tables hold the same bytes at the same place
/// in the same 72-byte block. `None` on a
/// pre-Fox version: its appearance travels in the savefile (PES 17's own
/// table reads a row at this place in this block, but its compile writes
/// the savefile instead).
pub(crate) fn row_offset(version: PesVersion) -> Option<usize> {
    match version {
        PesVersion::Pes18 | PesVersion::Pes19 => Some(128),
        PesVersion::Pes20 | PesVersion::Pes21 => Some(252),
        PesVersion::Pes15 | PesVersion::Pes16 | PesVersion::Pes17 => None,
    }
}

/// The widest bit width `field` is stored at in any version's player or
/// appearance record: the bound Team TOML's stored-ranges mode holds a value
/// to, so one document parses for every version. 0 for a field no version
/// stores.
pub(crate) fn widest_bit_width(field: PlayerField) -> u32 {
    PesVersion::ALL
        .into_iter()
        .filter_map(|version| bit_width(version, field))
        .max()
        .unwrap_or(0)
}

/// The biggest value `version`'s player or appearance record stores in
/// `field` (`2^width - 1`, the codec's `ValueTooWide` bound): the bound a
/// save's own field allows, wider than `settings.toml`'s ranges. `None`
/// where the version does not store the field.
pub fn player_max_value(version: PesVersion, field: PlayerField) -> Option<u64> {
    bit_width(version, field).map(|width| (1u64 << width) - 1)
}

/// `field`'s bit width in `version`'s player or appearance record — the
/// bound Team TOML's `apply` holds a stored value to so `write_player`
/// cannot refuse it afterwards. `None` where the version does not store the
/// field.
pub(crate) fn bit_width(version: PesVersion, field: PlayerField) -> Option<u32> {
    let schema = schema_for(version);
    schema.player.bit_width(field).or_else(|| {
        schema
            .appearance
            .as_ref()
            .and_then(|(_, appearance)| appearance.bit_width(field))
    })
}

/// The oldest version whose player (or appearance) record stores `field`;
/// `None` for a field no version stores. Behind the editors' disabled `PES
/// NN+` tooltips.
pub fn first_version_with(field: PlayerField) -> Option<PesVersion> {
    PesVersion::ALL
        .iter()
        .copied()
        .find(|version| schema_for(*version).player_has(field))
}

/// `first_version_with` for a team-record field (the Team tab's disabled
/// `PES NN+` tooltips): the oldest version whose team record stores
/// `field`; `None` for a field no version stores.
pub fn first_version_with_team(field: TeamField) -> Option<PesVersion> {
    PesVersion::ALL
        .iter()
        .copied()
        .find(|version| schema_for(*version).team.has(field))
}

/// The smallest `which` player text field over the versions it counts
/// (`spec/pes_savefile/operations.md` "Team TOML", the portable text
/// limits): the name over every version (46 bytes), the shirt name over PES
/// 15 and 17 to 21 (18 letters). PES 16's shirt field is the one outlier
/// left out (16 letters): `apply` onto a PES 16 save crops a longer shirt
/// name to the field's 16 with a note rather than hold every shirt name to
/// 16.
pub fn portable_text_max(which: PlayerText) -> usize {
    const SHIRT_VERSIONS: [PesVersion; 6] = [
        PesVersion::Pes15,
        PesVersion::Pes17,
        PesVersion::Pes18,
        PesVersion::Pes19,
        PesVersion::Pes20,
        PesVersion::Pes21,
    ];
    let versions: &[PesVersion] = match which {
        PlayerText::Name => &PesVersion::ALL,
        PlayerText::ShirtName => &SHIRT_VERSIONS,
    };
    versions
        .iter()
        .map(|version| crate::codec::text_max(schema_for(*version).player.texts, which))
        .min()
        .expect("a non-empty version list")
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Every bit run and text field of a record schema as half-open bit ranges.
    fn record_runs<F: Copy, T>(schema: &RecordSchema<F, T>) -> Vec<(u32, u32)> {
        let mut runs: Vec<(u32, u32)> = schema
            .fields
            .iter()
            .map(|f| (f.bit_offset, f.bit_offset + f.bit_width))
            .collect();
        for a in schema.arrays {
            for i in 0..u32::from(a.count) {
                let start = a.base_bit + i * a.stride_bits;
                runs.push((start, start + a.bit_width));
            }
        }
        for t in schema.texts {
            runs.push((t.byte_offset * 8, t.byte_offset * 8 + t.len * 8));
        }
        if let Some(run) = &schema.ingame_face {
            runs.push((run.byte_offset * 8, (run.byte_offset + run.len) * 8));
        }
        runs
    }

    /// The tactics record's runs, presets, formations and instructions expanded.
    fn tactics_runs(schema: &TacticsSchema) -> Vec<(u32, u32)> {
        let mut runs: Vec<(u32, u32)> = schema
            .fields
            .iter()
            .map(|f| (f.bit_offset, f.bit_offset + f.bit_width))
            .collect();
        for a in schema.arrays {
            for i in 0..u32::from(a.count) {
                let start = a.base_bit + i * a.stride_bits;
                runs.push((start, start + a.bit_width));
            }
        }
        for preset in 0..3u32 {
            let preset_base = preset * schema.preset_stride_bits;
            for p in schema.presets {
                let start = preset_base + p.bit_offset;
                runs.push((start, start + 8));
            }
            for slot in 0..11u32 {
                let start = preset_base + schema.man_marking_bit + slot * 8;
                runs.push((start, start + 8));
            }
            let f = &schema.formations;
            for formation in 0..3u32 {
                let base = preset_base + f.base_bit + formation * f.formation_stride_bits;
                for slot in 0..11u32 {
                    runs.push((
                        base + slot * f.slot_stride_bits,
                        base + slot * f.slot_stride_bits + 8,
                    ));
                    runs.push((
                        base + f.y_offset_bits + slot * f.pair_stride_bits,
                        base + f.y_offset_bits + slot * f.pair_stride_bits + 8,
                    ));
                    runs.push((
                        base + f.x_offset_bits + slot * f.pair_stride_bits,
                        base + f.x_offset_bits + slot * f.pair_stride_bits + 8,
                    ));
                }
            }
            if let Some(ins) = &schema.instructions {
                for side in 0..2u32 {
                    for index in 0..2u32 {
                        for part in 0..2u32 {
                            let start = preset_base
                                + ins.base_bit
                                + side * ins.side_stride_bits
                                + index * ins.index_stride_bits
                                + part * ins.part_stride_bits;
                            runs.push((start, start + ins.part_stride_bits));
                        }
                    }
                }
            }
        }
        runs
    }

    /// Asserts the half-open bit ranges do not overlap and lie inside `size` bytes.
    fn check_runs(runs: &mut [(u32, u32)], size: usize, what: &str) {
        runs.sort_unstable();
        for pair in runs.windows(2) {
            assert!(pair[0].1 <= pair[1].0, "{what}: runs {pair:?} overlap");
        }
        for &(start, end) in runs.iter() {
            assert!(
                end <= (size * 8) as u32,
                "{what}: run {start}..{end} past the record"
            );
        }
    }

    #[test]
    fn no_two_bit_runs_overlap_and_everything_is_inside_the_record() {
        for version in PesVersion::ALL {
            let schema = schema_for(version);
            check_runs(
                &mut record_runs(schema.player),
                schema.player.size,
                "player",
            );
            if let Some((_, appearance)) = &schema.appearance {
                check_runs(&mut record_runs(*appearance), appearance.size, "appearance");
            }
            check_runs(&mut record_runs(schema.team), schema.team.size, "team");
            check_runs(
                &mut record_runs(schema.roster),
                schema.roster.size,
                "roster",
            );
            check_runs(
                &mut tactics_runs(schema.tactic),
                schema.tactic.size,
                "tactic",
            );
        }
    }

    #[test]
    fn record_sizes_match_the_measured_layout() {
        let players = [112, 112, 188, 188, 188, 312, 312];
        let appearance = [Some(68), Some(72), None, None, None, None, None];
        let teams = [456, 456, 480, 480, 416, 528, 588];
        let rosters = [164, 164, 164, 164, 244, 284, 284];
        let tactics = [516, 520, 628, 628, 628, 628, 628];
        for (i, version) in PesVersion::ALL.iter().enumerate() {
            let schema = schema_for(*version);
            assert_eq!(schema.player.size, players[i], "{version:?} player");
            assert_eq!(
                schema.appearance.as_ref().map(|(_, a)| a.size),
                appearance[i],
                "{version:?} appearance"
            );
            assert_eq!(schema.team.size, teams[i], "{version:?} team");
            assert_eq!(schema.roster.size, rosters[i], "{version:?} roster");
            assert_eq!(schema.tactic.size, tactics[i], "{version:?} tactic");
        }
    }

    /// `has`/`has_preset` answer by version — the gating `team_toml`'s apply
    /// relies on.
    #[test]
    fn tactics_has_answers_by_version() {
        use crate::schema::fields::{PresetField, TacticsField};

        assert!(
            schema_for(PesVersion::Pes15)
                .tactic
                .has(TacticsField::AutoOffsideTrap)
        );
        assert!(
            !schema_for(PesVersion::Pes15)
                .tactic
                .has(TacticsField::AutoAttackDefenceLevels)
        );
        assert!(
            schema_for(PesVersion::Pes17)
                .tactic
                .has(TacticsField::AutoAttackDefenceLevels)
        );
        for version in PesVersion::ALL {
            let schema = schema_for(version);
            assert!(schema.tactic.has(TacticsField::Starting(3)), "{version:?}");
            assert!(
                schema.tactic.has_preset(PresetField::SupportRange),
                "{version:?}"
            );
            for preset in 0..3 {
                for slot in 0..11 {
                    assert!(
                        schema.tactic.has(TacticsField::ManMarking { preset, slot }),
                        "{version:?} preset {preset} slot {slot}"
                    );
                }
            }
            assert!(
                !schema
                    .tactic
                    .has(TacticsField::ManMarking { preset: 3, slot: 0 }),
                "{version:?}"
            );
            assert!(
                !schema.tactic.has(TacticsField::ManMarking {
                    preset: 0,
                    slot: 11
                }),
                "{version:?}"
            );
        }
        assert!(
            !schema_for(PesVersion::Pes15)
                .tactic
                .has_preset(PresetField::FluidFormation)
        );
        assert!(
            schema_for(PesVersion::Pes16)
                .tactic
                .has_preset(PresetField::FluidFormation)
        );
    }

    /// `player_has` answers for both records: a player-record field, an
    /// appearance-record field on 15/16, and a field the version lacks.
    #[test]
    fn player_has_covers_the_player_and_appearance_records() {
        assert!(schema_for(PesVersion::Pes19).player_has(PlayerField::Height));
        assert!(schema_for(PesVersion::Pes15).player_has(PlayerField::NeckLength));
        assert!(schema_for(PesVersion::Pes16).player_has(PlayerField::NeckLength));
        assert!(!schema_for(PesVersion::Pes15).player_has(PlayerField::TightPossession));
    }

    /// `max_value` reads `2^width - 1` from the field's own table row — a
    /// `fields` run (the id fields) and an `arrays` run (the kit-slot team
    /// bindings) — and `None` where the record lacks the field.
    #[test]
    fn max_value_reads_the_fields_own_width() {
        let pes21 = schema_for(PesVersion::Pes21);
        for field in [PlayerField::BootsId, PlayerField::GlovesId] {
            let width = pes21
                .player
                .fields
                .iter()
                .find(|spec| spec.field == field)
                .unwrap_or_else(|| panic!("{field:?} is stored on PES 21"))
                .bit_width;
            assert_eq!(
                pes21.player.max_value(field),
                Some((1u64 << width) - 1),
                "{field:?} is a {width}-bit field"
            );
        }
        // The kit-slot team binding comes through `arrays`, not `fields`.
        let width = schema_for(PesVersion::Pes17)
            .team
            .arrays
            .iter()
            .find(|array| (array.make)(0) == TeamField::KitSlotTeam(0))
            .expect("PES 17 stores kit slots")
            .bit_width;
        assert_eq!(
            schema_for(PesVersion::Pes17)
                .team
                .max_value(TeamField::KitSlotTeam(0)),
            Some((1u64 << width) - 1),
            "KitSlotTeam is a {width}-bit field"
        );
        assert_eq!(
            schema_for(PesVersion::Pes15)
                .team
                .max_value(TeamField::ManagerId),
            None,
            "PES 15 has no manager id"
        );
    }

    /// `player_max_value` is `2^width - 1` over whichever record holds the
    /// field: the player record on PES 21, the appearance record on PES 15;
    /// `None` for a field the version lacks.
    #[test]
    fn player_max_value_reads_whichever_record_holds_the_field() {
        let pes21 = schema_for(PesVersion::Pes21);
        let width = pes21
            .player
            .fields
            .iter()
            .find(|spec| spec.field == PlayerField::BootsId)
            .expect("PES 21's player record stores the boots id")
            .bit_width;
        assert_eq!(
            player_max_value(PesVersion::Pes21, PlayerField::BootsId),
            Some((1u64 << width) - 1),
            "PES 21's boots id is a {width}-bit field"
        );
        let pes15 = schema_for(PesVersion::Pes15);
        let (_, appearance) = pes15
            .appearance
            .as_ref()
            .expect("PES 15 has an appearance record");
        let width = appearance
            .fields
            .iter()
            .find(|spec| spec.field == PlayerField::BootsId)
            .expect("PES 15's appearance record stores the boots id")
            .bit_width;
        assert_eq!(
            player_max_value(PesVersion::Pes15, PlayerField::BootsId),
            Some((1u64 << width) - 1),
            "PES 15's boots id is a {width}-bit field"
        );
        assert_eq!(
            player_max_value(PesVersion::Pes15, PlayerField::DribblingMotion),
            None,
            "PES 15 has no dribbling motion"
        );
    }

    /// `first_version_with` answers the oldest storing version: a field of
    /// every version, the version-gated ones, and `None` for a field no
    /// version's player record stores.
    #[test]
    fn first_version_with_names_the_oldest_storing_version() {
        assert_eq!(
            first_version_with(PlayerField::Speed),
            Some(PesVersion::Pes15)
        );
        assert_eq!(
            first_version_with(PlayerField::Clearing),
            Some(PesVersion::Pes16)
        );
        assert_eq!(
            first_version_with(PlayerField::PhysicalContact),
            Some(PesVersion::Pes17)
        );
        assert_eq!(
            first_version_with(PlayerField::Star),
            Some(PesVersion::Pes19)
        );
        assert_eq!(
            first_version_with(PlayerField::StrongerHand),
            Some(PesVersion::Pes20)
        );
        assert_eq!(first_version_with(PlayerField::Skill(60)), None);
    }

    /// `first_version_with_team` answers the oldest version whose team
    /// record stores the field: the kit slots' PES 17, and the manager
    /// id's, computed the same way the tooltip's `PES NN+` reads it.
    #[test]
    fn first_version_with_team_names_the_oldest_storing_version() {
        assert_eq!(
            first_version_with_team(TeamField::KitSlotTeam(0)),
            Some(PesVersion::Pes17),
            "the kit slots are PES 17 only"
        );
        let expected = PesVersion::ALL
            .iter()
            .copied()
            .find(|version| schema_for(*version).team.has(TeamField::ManagerId));
        assert_eq!(
            expected,
            Some(PesVersion::Pes19),
            "the Team tab's tooltip says PES 19+"
        );
        assert_eq!(first_version_with_team(TeamField::ManagerId), expected);
    }

    /// The portable limits are the shortest fields of the versions they
    /// count: 46 bytes of name over every version, 18 shirt-name letters
    /// over PES 15 and 17 to 21 (PES 16's 16 left out).
    #[test]
    fn portable_text_max_is_the_shortest_field_of_its_versions() {
        assert_eq!(portable_text_max(PlayerText::Name), 46);
        assert_eq!(portable_text_max(PlayerText::ShirtName), 18);
    }

    /// `bit_width` reads the `arrays` runs' own widths, not only the
    /// `fields` rows': the positions are 2-bit elements and the com styles
    /// 1-bit, `None` past each version's array, and `widest_bit_width`
    /// takes the widest over the versions.
    #[test]
    fn array_fields_have_their_array_width() {
        // Every version's player schema holds thirteen positions (an `arrays`
        // run on 15-17, thirteen `fields` rows on 18-21) and seven com
        // styles (an `arrays` run on every version).
        let (positions, styles) = (13, 7);
        for version in PesVersion::ALL {
            for i in 0..positions {
                assert_eq!(
                    bit_width(version, PlayerField::PlayablePosition(i)),
                    Some(2),
                    "{version:?} PlayablePosition({i})"
                );
            }
            assert_eq!(
                bit_width(version, PlayerField::PlayablePosition(positions)),
                None,
                "{version:?} holds only {positions} positions"
            );
            for i in 0..styles {
                assert_eq!(
                    bit_width(version, PlayerField::ComStyle(i)),
                    Some(1),
                    "{version:?} ComStyle({i})"
                );
            }
            assert_eq!(
                bit_width(version, PlayerField::ComStyle(styles)),
                None,
                "{version:?} holds only {styles} com styles"
            );
        }
        assert_eq!(widest_bit_width(PlayerField::PlayablePosition(0)), 2);
        // Seven com styles per version: index 6 is the last any holds.
        assert_eq!(widest_bit_width(PlayerField::ComStyle(6)), 1);
    }
}
